import Foundation

#if canImport(AppKit)
import AppKit
#endif

/// Privacy and security evaluation for clipboard contents.
public final class PasteboardPrivacyFilter: Sendable {
    public init() {}

    /// Sensitive or transient pasteboard types that must NEVER be synchronized across devices.
    public static let sensitiveTypeIdentifiers: Set<String> = [
        // 1Password, Bitwarden, KeePass, and general password managers
        "org.nspasteboard.ConcealedType",
        "com.agilebits.onepassword",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        // Butler, LaunchBar, Keyboard Maestro transient types
        "de.petermaurer.TransientPasteboardType",
        // Maccy / Paste transient flags
        "net.p0deje.maccy.transient",
        // TextExpander transient types
        "com.smileonmymac.textexpander.transient"
    ]

    /// Checks if a list of pasteboard UTI types contains any concealed or transient types.
    public func isSafeToSync(typeIdentifiers: [String]) -> Bool {
        for type in typeIdentifiers {
            if Self.sensitiveTypeIdentifiers.contains(type) {
                return false
            }
        }
        return true
    }

    #if canImport(AppKit)
    /// Checks if the current contents of an NSPasteboard are safe to synchronize.
    @MainActor
    public func isSafeToSync(pasteboard: NSPasteboard) -> Bool {
        guard let types = pasteboard.types else { return false }
        let typeStrings = types.map { $0.rawValue }
        return isSafeToSync(typeIdentifiers: typeStrings)
    }

    /// Returns only the safe, non-sensitive types present on the pasteboard item.
    @MainActor
    public func filterSafeTypes(from item: NSPasteboardItem) -> [NSPasteboard.PasteboardType] {
        item.types.filter { type in
            !Self.sensitiveTypeIdentifiers.contains(type.rawValue)
        }
    }
    #endif
}
